import {C as store,A as outfits,B as scenes,J as requirements,Y as stats} from './index-BLVOhKhN.js?v=20261007-loading6';
import {petNames,petLevel,firstGoal,goalView,celebrationToken} from './companion-goals-state-20261004.js?v=2';
import {spriteStyle} from './companion-art-20261004.js';
const KEY='lux-companion-experience-v1',PET='lux-pet-companion-v1',catalog={outfits,scenes,requirements,stats};
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function read(key){try{return JSON.parse(localStorage.getItem(key)||'{}')||{}}catch{return {}}}
function save(next){try{localStorage.setItem(KEY,JSON.stringify(next));schedule();return true}catch{announce('Could not save your reward choice. Please try again.');return false}}
let noticeTimer;function announce(copy){let el=document.getElementById('companion-notice');if(!el){el=document.createElement('p');el.id='companion-notice';el.setAttribute('role','status');document.body.append(el)}el.textContent=copy;clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>el.remove(),4200);}
function pet(){const p=read(PET);return {...p,species:petNames[p.species]?p.species:'moss-hornling'};}
function view(){const p=pet(),prefs=read(KEY);return goalView(prefs.goal||firstGoal(p),store.getState(),p,catalog);}
function art(v){return v.kind==='pet'?`<span class="cx-art" role="img" aria-label="${esc(v.name)}" style="${spriteStyle(v.id,v.target)}"></span>`:`<img class="cx-art ${v.kind==='scene'?'cx-scene':''}" src="${esc(v.art)}" alt="${esc(v.name)}" loading="lazy">`;}
function dialog(id,title){let d=document.getElementById(id);if(!d){d=document.createElement('dialog');d.id=id;d.className='cx-dialog';d.setAttribute('aria-label',title);document.body.append(d)}return d;}
function picker(){const d=dialog('companion-goal-picker','Choose your reward goal');const p=pet();d.innerHTML=`<div class="cx-dialog-head"><h2>What are you working towards?</h2><button data-close>Close</button></div><p>Choose a goal. Your existing unlock requirements stay the same.</p><div class="cx-tabs"><button data-kind="pet">Pet evolution</button><button data-kind="outfit">Outfits</button><button data-kind="scene">Backgrounds</button></div><label class="cx-search">Find a reward <input type="search" placeholder="Search by name"></label><div class="cx-goal-grid"></div>`;
 let kind='pet';const list=()=>{const needle=d.querySelector('input').value.trim().toLowerCase();const goals=kind==='pet'?Array.from({length:Math.max(0,5-petLevel(p,p.species))},(_,i)=>({kind,id:p.species,level:petLevel(p,p.species)+i+1})):(kind==='scene'?scenes:outfits).filter(x=>!x.free&&x.id!=='day').map(x=>({kind,id:x.id}));const grid=d.querySelector('.cx-goal-grid');grid.replaceChildren();for(const g of goals){const v=goalView(g,store.getState(),p,catalog);if(!v||!v.name.toLowerCase().includes(needle))continue;const b=document.createElement('button');b.className='cx-goal-option';b.innerHTML=`${art(v)}<strong>${esc(v.name)}</strong><small>${esc(v.detail)}</small><span>Set this goal</span>`;b.addEventListener('click',()=>{if(save({...read(KEY),goal:g})){d.close();announce(`Goal selected: ${v.name}`)}});grid.append(b)}if(!grid.children.length)grid.innerHTML='<p>No matching rewards. Try another category or search.</p>';d.querySelectorAll('[data-kind]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.kind===kind)));};
 d.querySelector('[data-close]').onclick=()=>d.close();d.querySelectorAll('[data-kind]').forEach(b=>b.onclick=()=>{kind=b.dataset.kind;list()});d.querySelector('input').oninput=list;list();d.showModal();}
function useGoal(v){const current=view();if(!current||!current.ready||current.kind!==v.kind||current.id!==v.id)return;
 if(v.kind==='pet'){location.href='/pet/#petGrowth';return;}
 const s=store.getState();if(v.kind==='outfit')s.equipOutfit(v.id);else s.equipScene(v.id);
 const after=store.getState(),ok=(v.kind==='outfit'?after.equippedOutfit:after.equippedScene)===v.id;
 if(ok){announce(`${v.name} is now equipped.`);document.getElementById('companion-goal-reveal')?.close();schedule()}else announce('This reward is still locked. Your progress is unchanged.');}
function reveal(v){if(!v?.ready)return;const d=dialog('companion-goal-reveal','Your reward goal is ready');d.innerHTML=`<div class="cx-reveal"><p class="cx-kicker">${v.unlocked?'YOUR GOAL IS UNLOCKED':'EVOLUTION IS READY'}</p>${art(v)}<h2>${esc(v.name)}</h2><p>${v.kind==='pet'&&!v.unlocked?`${v.balance} MP available. Evolution still requires a separate choice in Companion Corner.`:'Your reward is ready. Use it now or keep it for later.'}</p><button data-use>${v.kind==='pet'?'Open evolution':v.kind==='scene'?'Use this background':'Wear this outfit'}</button><button data-skip>Skip celebration</button></div>`;d.querySelector('[data-use]').onclick=()=>useGoal(v);d.querySelector('[data-skip]').onclick=()=>d.close();d.showModal();const prefs=read(KEY);save({...prefs,seen:[...new Set([...(prefs.seen||[]),celebrationToken(v)])].slice(-100)});}
let reaction='ready',answers=0,reactTimer;
function companionMarkup(copy){const p=pet(),name=p.name||petNames[p.species];return `<span class="cx-pet-art" role="img" aria-label="${esc(name)}" style="${spriteStyle(p.species,petLevel(p,p.species))}"></span><div><strong>${esc(name)} is beside you</strong><p data-companion-copy>${esc(copy)}</p></div><button data-motion aria-pressed="${!!read(KEY).quiet}">${read(KEY).quiet?'Animations off':'Reduce animations'}</button>`;}
function wireMotion(el){el.querySelector('[data-motion]').onclick=()=>save({...read(KEY),quiet:!read(KEY).quiet});}
function skipAnimation(){document.querySelectorAll('.cx-answer-flash,.cx-finish,.cx-session-rewards').forEach(el=>{el.dataset.reaction='ready';el.classList.add('cx-skipped')});document.getElementById('study-companion')?.setAttribute('data-reaction','ready');}
function rewardSummary(results){
 const v=view(),xp=results.dataset.sessionXp,stars=results.querySelector('[data-memory-recovered-ids]')?.dataset.memoryRecoveredIds;let ids=[];try{ids=JSON.parse(stars||'[]')}catch{}
 const added=Number(results.querySelector('[data-memory-stars-added]')?.dataset.memoryStarsAdded)||0;
 let panel=results.querySelector('.cx-session-rewards');if(!panel){panel=document.createElement('section');panel.className='cx-session-rewards';panel.setAttribute('aria-label','Rewards this session');results.querySelector('h1')?.after(panel)}
 const sig=JSON.stringify([xp,added,v,store.getState().sound]);if(panel.dataset.signature===sig)return;panel.dataset.signature=sig;
 panel.innerHTML=`<p class="cx-kicker">THIS SET’S REWARDS</p><div class="cx-reward-totals"><div><strong>${xp===undefined?'Recorded':`+${esc(xp)}`}</strong><span>Scholar XP</span></div><div><strong>+${added}</strong><span>Memory ${added===1?'star':'stars'}</span></div></div>${v?`<div class="cx-session-goal">${art(v)}<div><strong>${esc(v.name)}</strong><p>${esc(v.detail)}</p>${v.rows.map(r=>`<progress value="${r.current}" max="${Math.max(1,r.target)}" aria-label="${esc(r.label)}"></progress>`).join('')}</div></div>`:'<button data-choose>Choose your reward goal</button>'}<div class="cx-actions"><button data-skip>Skip animation</button><button data-motion aria-pressed="${!!read(KEY).quiet}">${read(KEY).quiet?'Animations off':'Reduce animations'}</button><button data-sound aria-pressed="${!!store.getState().sound}">${store.getState().sound?'Sound on':'Sound off'}</button></div>`;
 panel.querySelector('[data-skip]').onclick=skipAnimation;wireMotion(panel);panel.querySelector('[data-choose]')?.addEventListener('click',picker);panel.querySelector('[data-sound]').onclick=()=>store.getState().setSound?.(!store.getState().sound);
}

let pendingBiologyForm=null;document.addEventListener('submit',e=>{const form=e.target.closest?.('[data-biology-question]');if(form&&form.querySelector('textarea:not(:disabled)')?.value.trim())pendingBiologyForm=form},true);
function refresh(){if(pendingBiologyForm){const result=pendingBiologyForm.querySelector('[role="status"] strong');if(result){pendingBiologyForm=null;reactToAnswer({detail:{correct:/·\s*Correct$/.test(result.textContent)}})}}const main=document.querySelector('main');if(!main)return;if(/^\/play\/?$/.test(location.pathname))main.querySelector("header")?.classList.add("cx-play-header");const prefs=read(KEY),p=pet();document.documentElement.classList.toggle('cx-quiet',!!prefs.quiet);document.querySelectorAll('[data-motion]').forEach(b=>{b.setAttribute('aria-pressed',String(!!prefs.quiet));const text=prefs.quiet?'Animations off':'Reduce animations';if(b.textContent!==text)b.textContent=text});
 const learning=/^\/study\/[^/]+\/(practise|play)/.test(location.pathname)||location.pathname.startsWith('/session/')||location.pathname.startsWith('/play/');
 let buddy=document.getElementById('study-companion');if(!learning){buddy?.remove()}else{if(!buddy){buddy=document.createElement('section');buddy.id='study-companion';buddy.className='cx-study-buddy';buddy.setAttribute('aria-label','Your study companion');const scholar=main.querySelector('aside');if(scholar)(scholar.closest("header")||scholar).after(buddy);else main.prepend(buddy)}const sig=`${p.species}|${p.name}|${petLevel(p,p.species)}|${prefs.quiet}`;if(buddy.dataset.signature!==sig){buddy.dataset.signature=sig;buddy.innerHTML=companionMarkup('Let’s take one question at a time.');wireMotion(buddy)}buddy.dataset.reaction=reaction;
 const results=main.querySelector('[aria-label="Session result"]');if(results)rewardSummary(results);if(results&&!results.querySelector('.cx-finish')){const finish=document.createElement('div');finish.className='cx-finish cx-study-buddy';finish.dataset.reaction='celebrate';finish.innerHTML=companionMarkup('Set complete. You kept going — let’s see your progress.');wireMotion(finish);results.append(finish);setTimeout(()=>{finish.dataset.reaction='ready'},2200);}}
 const host=location.pathname==='/'?document.getElementById('school-revision-home'):null;let panel=document.getElementById('chosen-reward-goal');if(!host){panel?.remove();const v=view(),token=celebrationToken(v);if(main.querySelector('[aria-label="Session result"]')&&token&&!(prefs.seen||[]).includes(token)&&!document.querySelector('.cx-dialog[open]'))reveal(v);return}if(!panel){panel=document.createElement('section');panel.id='chosen-reward-goal';panel.className='cx-chosen-goal';panel.setAttribute('aria-label','Your chosen reward goal');host.append(panel)}const v=view(),sig=JSON.stringify([v,prefs.quiet]);if(panel.dataset.signature!==sig){panel.dataset.signature=sig;panel.innerHTML=v?`${art(v)}<div><p class="cx-kicker">YOUR CHOSEN REWARD</p><h3>${esc(v.name)}</h3><p>${esc(v.detail)}</p><div class="cx-requirements">${v.rows.map(r=>`<p>${esc(r.label)} · ${r.current} / ${r.target}<progress value="${r.current}" max="${Math.max(1,r.target)}" aria-label="${esc(r.label)}"></progress></p>`).join('')}</div><div class="cx-actions"><button data-choose>Change reward goal</button>${v.ready?'<button data-ready>View ready reward</button>':''}</div></div>`:'<div><h3>Choose your next reward</h3><button data-choose>Choose a reward goal</button></div>';panel.querySelector('[data-choose]').onclick=picker;panel.querySelector('[data-ready]')?.addEventListener('click',()=>reveal(v))}
 const token=celebrationToken(v);if(token&&!(prefs.seen||[]).includes(token)&&!document.querySelector('.cx-dialog[open]'))reveal(v);
}
let queued=false;function schedule(){if(queued)return;queued=true;queueMicrotask(()=>{queued=false;refresh()})}
function reactToAnswer(e){if(!document.getElementById('study-companion'))return;answers++;reaction=e.detail?.correct?'success':'thinking';if(e.detail?.correct){let flash=document.querySelector('.cx-answer-flash');if(!flash){flash=document.createElement('div');flash.className='cx-answer-flash';flash.setAttribute('role','status');document.body.append(flash)}flash.classList.remove('cx-skipped');flash.innerHTML='<span aria-hidden="true">✦</span><strong>Correct!</strong><button>Skip animation</button>';flash.dataset.reaction='success';flash.querySelector('button').onclick=skipAnimation;setTimeout(()=>flash.remove(),850)}const b=document.getElementById('study-companion');b.dataset.reaction=reaction;const text=b.querySelector('[data-companion-copy]');text.textContent=e.detail?.correct?'That was a good step. Keep going.':'Take your time. Let’s work through the explanation.';clearTimeout(reactTimer);reactTimer=setTimeout(()=>{reaction='ready';b.dataset.reaction='ready';text.textContent=answers>=12?'A little pause is welcome when you need it.':'I’m here for the next question.'},2200)}
window.addEventListener('scholar:question-answered',reactToAnswer);
store.subscribe(schedule);window.addEventListener('storage',schedule);window.addEventListener('scholar:pet-changed',schedule);window.addEventListener('pageshow',schedule);window.addEventListener('popstate',schedule);
new MutationObserver(schedule).observe(document.documentElement,{childList:true,subtree:true});const css=document.createElement('link');css.rel='stylesheet';css.href='/assets/companion-experience-20261004.css?v=7';document.head.append(css);schedule();
